#include <vector>
#include <iostream>
#include <stdexcept>

int main() {
    std::vector<int> v = {10, 20};

    // 1. Safe access (throws exception)
    try {
        v.at(2) = 30; 
    } catch (const std::out_of_range& e) {
        std::cerr << "Error: " << e.what() << "\n";
    }

    // 2. Fast, unsafe access (Undefined Behavior if index >= size())
    // v[2] = 30; // DANGER: UB, size is only 2
    v[1] = 25; // Safe, index 1 is valid
}
